// Sanitized classifier corpus — the committed, tracked fixture for the Tier A
// real-OCR regression test (classifierRealOcr.integration.test.ts). Derived
// from real PaddleOCR line-text (document-pipeline-demo set + founder-supplied
// documents), but every third-party AND founder PII value has been replaced
// with consistent synthetic equivalents: names, addresses, emails, phones,
// tax registrations (GST/HST/PST), and account / order / card / reference /
// transaction numbers. Amounts, dates, generic product descriptions, and all
// document-structure tokens (Invoice/Bill/Statement headers, receipt and
// payment footers) are preserved verbatim — the classifier keys ONLY on those
// structural tokens, so sanitization does not change any classification.
//
// Regeneration: apps/web/scripts/capture-real-ocr-fixtures.ts writes the RAW
// OCR text to corpus.ts in this directory (real PII). corpus.ts is git-ignored
// and stays local-only; THIS sanitized file is what ships. After regenerating,
// re-apply the sanitization before committing — never commit raw corpus.ts.
// The source PDFs/PNGs are git-ignored too.
//
// expectedType is the correct classification. The corpus test asserts Tier A
// returns expectedType OR abstains (no-match → Tier C); it must never return
// a different type (the high-precision / overfit guard).

export type RealOcrExpectedType =
  | 'vendor_invoice'
  | 'receipt'
  | 'payment_confirmation';

export interface RealOcrFixture {
  label: string;
  source: 'demo' | 'founder';
  expectedType: RealOcrExpectedType;
  captureError?: string;
  lines: string[];
}

